class CPTExtendedService:
    @staticmethod
    def get_procedure(code: str) -> Optional[CPTDetailedRecord]:
        return CPT_EXTENDED_DATABASE.get(code.strip())

    @staticmethod
    def search_procedures(query: str) -> List[CPTDetailedRecord]:
        q = query.lower().strip()
        return [p for p in CPT_EXTENDED_DATABASE.values() if q in p.cpt_code or q in p.procedure_title.lower()][:50]
